import {initializeTestEnvironment,assertSucceeds,assertFails} from '@firebase/rules-unit-testing';
import {doc,getDoc,setDoc,serverTimestamp} from 'firebase/firestore';
import fs from 'fs';
const env=await initializeTestEnvironment({projectId:'demo-la',firestore:{rules:fs.readFileSync(process.env.RULES||'firestore.rules','utf8'),host:'127.0.0.1',port:8089}});
const U='u1';
await env.withSecurityRulesDisabled(async c=>{const d=c.firestore();
 await setDoc(doc(d,'usernames',U),{uid:U,username:'Pat',usernameLower:'pat',guest:false});
 await setDoc(doc(d,'arcadePlayers',U),{username:'Pat',lp:1000,games:{crema:{lp:1000,best:1,plays:2,last:1}},prog:{},updatedAt:new Date()});});
const db=env.authenticatedContext(U,{firebase:{sign_in_provider:'password'}}).firestore();
const row=(extra)=>Object.assign({username:'Pat',lp:1100,games:{crema:{lp:1100,best:1,plays:3,last:1}},prog:{},updatedAt:serverTimestamp()},extra);
const R=[];const t=async(name,p,want)=>{try{await (want?assertSucceeds(p):assertFails(p));R.push('PASS '+name);}catch(e){R.push('FAIL '+name+' '+e.message.slice(0,120));}};
await t('game points, no live doc (old client)',setDoc(doc(db,'arcadePlayers',U),row()),false);
await t('claim live tab',setDoc(doc(db,'arcadeLive',U),{tab:'T1',game:'crema',at:serverTimestamp()}),true);
await t('game points from old client (no liveTab)',setDoc(doc(db,'arcadePlayers',U),row()),false);
await t('game points from frozen tab (wrong liveTab)',setDoc(doc(db,'arcadePlayers',U),row({liveTab:'T0'})),false);
await t('game points from live tab',setDoc(doc(db,'arcadePlayers',U),row({liveTab:'T1'})),true);
await t('bonus-only write without liveTab',setDoc(doc(db,'arcadePlayers',U),{username:'Pat',lp:1300,games:{crema:{lp:1100,best:1,plays:3,last:1},bonus:{lp:200,best:0,plays:0,last:0}},prog:{},updatedAt:serverTimestamp()}),true);
await t('LP-neutral write (pins etc.)',setDoc(doc(db,'arcadePlayers',U),{username:'Pat',lp:1300,games:{crema:{lp:1100,best:1,plays:3,last:1},bonus:{lp:200,best:0,plays:0,last:0}},prog:{x:1},updatedAt:serverTimestamp()}),true);
const sv=(tab)=>Object.assign({data:'{}',major:3,minor:2,progress:1,updatedAt:serverTimestamp()},tab?{liveTab:tab}:{});
await t('save from live tab',setDoc(doc(db,'arcadeSaves',U,'games','crema'),sv('T1')),true);
await t('save from old client',setDoc(doc(db,'arcadeSaves',U,'games','crema'),sv(null)),false);
await t('save from frozen tab',setDoc(doc(db,'arcadeSaves',U,'games','crema'),sv('T0')),false);
await t('read own grants',getDoc(doc(db,'arcadeGrants',U)),true);
await t('write own grants',setDoc(doc(db,'arcadeGrants',U),{items:[]}),false);
await t('read other live',getDoc(doc(env.authenticatedContext('u2',{firebase:{sign_in_provider:'password'}}).firestore(),'arcadeLive',U)),false);
// brand-new player create (no live doc needed)
await env.withSecurityRulesDisabled(async c=>{await setDoc(doc(c.firestore(),'usernames','u3'),{uid:'u3',username:'New',usernameLower:'new',guest:false});});
const db3=env.authenticatedContext('u3',{firebase:{sign_in_provider:'password'}}).firestore();
await t('new player first write',setDoc(doc(db3,'arcadePlayers','u3'),{username:'New',lp:50,games:{crema:{lp:50,best:1,plays:1,last:1}},prog:{},updatedAt:serverTimestamp()}),true);
// community game counter branches may ONLY touch the counter (no content/ownership tampering)
await env.withSecurityRulesDisabled(async c=>{await setDoc(doc(c.firestore(),'communityGames','g1'),{ownerUid:'owner1',ownerName:'Owner',title:'Game',data:'ORIG',engine:'studio2d',status:'live',plays:5,likes:0,createdAt:new Date(),updatedAt:new Date()});});
const atk=env.authenticatedContext('atk',{firebase:{sign_in_provider:'password'}}).firestore();
await t('clean play +1',setDoc(doc(atk,'communityGames','g1'),{plays:6},{merge:true}),true);
await t('play +1 cannot rewrite game code',setDoc(doc(atk,'communityGames','g1'),{plays:7,data:'HACKED'},{merge:true}),false);
await t('play +1 cannot steal ownership',setDoc(doc(atk,'communityGames','g1'),{plays:7,ownerUid:'atk'},{merge:true}),false);
await t('play +1 cannot inflate likes',setDoc(doc(atk,'communityGames','g1'),{plays:7,likes:9999},{merge:true}),false);
await t('play write cannot change title only',setDoc(doc(atk,'communityGames','g1'),{title:'Pwned'},{merge:true}),false);

// ----- Crema Metro (multiplayer city)
await env.withSecurityRulesDisabled(async c=>{await setDoc(doc(c.firestore(),'arcadeRoles','boss'),{role:'creator',username:'Boss'});});
const mpA=env.authenticatedContext('pa',{firebase:{sign_in_provider:'password'}}).firestore(),mpB=env.authenticatedContext('pb',{firebase:{sign_in_provider:'password'}}).firestore(),mpBoss=env.authenticatedContext('boss',{firebase:{sign_in_provider:'password'}}).firestore();
const pres=(n)=>({n:n,x:1.5,z:-3,r:0,a:'city',v:'',c:1,h:0,lv:3,at:serverTimestamp()});
await t('mp presence own',setDoc(doc(mpA,'cremaMpPresence','pa'),pres('A')),true);
await t('mp presence someone else',setDoc(doc(mpA,'cremaMpPresence','pb'),pres('A')),false);
const lot=(o,on,sale,extra)=>Object.assign({o:o,on:on,k:'biz',nm:'Corner Deli',pr:1,sale:sale,at:serverTimestamp()},extra||{});
await t('mp claim free lot',setDoc(doc(mpA,'cremaMpLots','20:d1:1:0'),lot('pa','A',0)),true);
await t('mp steal owned lot',setDoc(doc(mpB,'cremaMpLots','20:d1:1:0'),lot('pb','B',0)),false);
await t('mp owner lists it',setDoc(doc(mpA,'cremaMpLots','20:d1:1:0'),lot('pa','A',5000)),true);
await t('mp buy without paying',setDoc(doc(mpB,'cremaMpLots','20:d1:1:0'),lot('pb','B',0)),false);
const {writeBatch}=await import('firebase/firestore');const bt=writeBatch(mpB);bt.set(doc(mpB,'cremaMpInbox','pa','items','20:d1:1:0-pb'),{f:'pb',fn:'B',amt:5000,why:'Bought Corner Deli',kind:'sale',at:serverTimestamp()});bt.set(doc(mpB,'cremaMpLots','20:d1:1:0'),lot('pb','B',0));
await t('mp buy listed lot and pay',bt.commit(),true);
await t('mp roastery door by player',setDoc(doc(mpA,'cremaMpLots','roastdoor'),lot('pa','A',0,{k:'door'})),false);
await t('mp roastery door by creator',setDoc(doc(mpBoss,'cremaMpLots','roastdoor'),lot('boss','Boss',0,{k:'door'})),true);
await t('mp inbox read other',getDoc(doc(mpB,'cremaMpInbox','pa','items','20:d1:1:0-pb')),false);
await t('mp vote own',setDoc(doc(mpA,'cremaMpVotes','m1','v','pa'),{y:true,at:serverTimestamp()}),true);
await t('mp vote for someone',setDoc(doc(mpA,'cremaMpVotes','m1','v','pb'),{y:true,at:serverTimestamp()}),false);
console.log(R.join('\n'));await env.cleanup();if(R.some(x=>x.startsWith('FAIL')))process.exit(1);
